import {ToolRegistry} from './registry.js';

it('rejects numeric location with the expected string type @specs/hal-engine-tool-input-validation/spec.md#2', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {
      name: 'weather',
      description: 'Weather',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
    },
    async input => JSON.stringify(input)
  );

  const response = await registry.execute('weather', {location: 8675309});

  expect(response.result).toMatch(/location.*string/);
  expect(response.result).not.toContain('8675309');
});
